<?php
require_once '../includes/auth.php'; requireActiveUser(); requireTenantContext(); requireModulePermission('hotspot','edit');
global $conn; $tenantId=(int)getCurrentTenantId(); $id=(int)($_GET['id']??0); $error='';
$q=$conn->prepare("SELECT * FROM hotspot_packages WHERE id=? AND tenant_id=?"); $q->bind_param('ii',$id,$tenantId); $q->execute(); $plan=$q->get_result()->fetch_assoc(); $q->close();
if(!$plan){http_response_code(404);exit('Hotspot plan not found.');}
if($_SERVER['REQUEST_METHOD']==='POST'){requireCsrf();$name=trim($_POST['name']??'');$duration=max(1,(int)($_POST['duration_minutes']??60));$price=max(0,(float)($_POST['price']??0));$status=$_POST['status']??'active';
if($name==='')$error='Plan name is required.';else{$q=$conn->prepare("UPDATE hotspot_packages SET name=?,duration_minutes=?,price=?,status=? WHERE id=? AND tenant_id=?");$q->bind_param('sidsii',$name,$duration,$price,$status,$id,$tenantId);if(!$q->execute())$error=$q->error?:'Unable to update plan.';else redirect('packages.php');$q->close();}}
$pageTitle='Edit Hotspot Plan';require_once '../includes/header.php';?>
<div class="dashboard-card"><h2>Edit Hotspot Plan</h2><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><form method="post"><?=csrfField()?><div class="form-group"><label>Plan Name</label><input name="name" required value="<?=e($plan['name'])?>"></div><div class="form-group"><label>Duration (minutes)</label><input type="number" min="1" name="duration_minutes" required value="<?=e($plan['duration_minutes'])?>"></div><div class="form-group"><label>Price (KES)</label><input type="number" step="0.01" min="0" name="price" required value="<?=e($plan['price'])?>"></div><div class="form-group"><label>Status</label><select name="status"><option value="active" <?=$plan['status']==='active'?'selected':''?>>Active</option><option value="inactive" <?=$plan['status']!=='active'?'selected':''?>>Inactive</option></select></div><button type="submit">Update Plan</button> <a href="packages.php">Cancel</a></form></div><?php require_once '../includes/footer.php';?>